/**
 * Builds the repository's site (GitHub Pages) from the one place each server
 * says what it is: its package.json `mcp` block, its README, and the code the
 * root README's table is generated by. A landing page with the two audiences
 * that ship and the extras, a page per audience, and a page per server that
 * renders its README, which stays the documentation: the site holds no second
 * copy of any of it, only labels and layout. `npm run check` builds it, so a
 * README or package.json the site cannot show fails there, as does a link
 * that leads nowhere; .github/workflows/pages.yml deploys it from main.
 *
 *   npx tsx scripts/site.ts [--out <dir>]     build into <dir> (default _site), then check its links
 *   npx tsx scripts/site.ts --topics          print the repository's GitHub topics, comma-separated
 */
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { INK, SITE_GLYPH, TILE, iconSvg } from "./icons.js";
import { AUDIENCE, AUDIENCES, readManifest, SITE, TOPICS_MAX, topicsOf, type Manifest } from "./packaging.js";
import { reachLine } from "./readme.js";
import { checkSite, resolveHref, type Layout } from "./site/links.js";
import { githubSlug } from "./site/markdown.js";
import { audiencePage, landingPage, notFoundPage, serverPage, type Page, type Repository, type Resolvers, type Server } from "./site/pages.js";

const ROOT = fileURLToPath(new URL("..", import.meta.url));

/** The fonts the site serves itself (no request to anyone else), and the subsets it needs: English and Romanian. */
const FONTS = [
  { pkg: "@fontsource-variable/space-grotesk", stem: "space-grotesk" },
  { pkg: "@fontsource-variable/inter", stem: "inter" },
] as const;
const SUBSETS = ["latin", "latin-ext"] as const;

/** A font package's folder. */
const fontDir = (pkg: string): string => dirname(createRequire(import.meta.url).resolve(`${pkg}/LICENSE`));

/**
 * The @font-face rules of the subsets the site serves, as the font package
 * writes them, pointing at the copies in assets/fonts/; and those files.
 */
const fontFaces = (): { readonly css: string; readonly files: readonly { readonly from: string; readonly to: string }[] } => {
  const faces = FONTS.flatMap(({ pkg, stem }) => {
    const dir = fontDir(pkg);
    const css = readFileSync(join(dir, "index.css"), "utf8");
    return SUBSETS.map((subset) => {
      const file = `${stem}-${subset}-wght-normal.woff2`;
      const rule = new RegExp(`/\\* ${stem}-${subset}-wght-normal \\*/\\s*(@font-face \\{[^}]*\\})`).exec(css)?.[1];
      if (rule === undefined) throw new Error(`${pkg}/index.css has no ${subset} face; the site serves ${SUBSETS.join(" and ")}`);
      return { rule: rule.replace(`./files/${file}`, `fonts/${file}`), file: { from: join(dir, "files", file), to: `assets/fonts/${file}` } };
    });
  });
  return { css: faces.map((f) => f.rule).join("\n"), files: faces.map((f) => f.file) };
};

type Built = { readonly pages: readonly Page[]; readonly servers: readonly Server[]; readonly problems: readonly string[] };

/** Every server's manifest, or the problems check-docs reports for it. */
const readServers = (): { readonly servers: readonly Server[]; readonly problems: readonly string[] } => {
  const read = readdirSync(join(ROOT, "servers"))
    .sort()
    .map((server) => ({ server, ...readManifest(ROOT, server) }));
  const problems = read.flatMap((r) => r.problems.map((p) => `servers/${r.server}: ${p}`));
  const servers = read
    .filter((r): r is typeof r & { manifest: Manifest } => r.manifest !== undefined)
    .map(({ manifest }) => {
      const readme = readFileSync(join(ROOT, manifest.repository.directory, "README.md"), "utf8");
      return { manifest, readme, reach: reachLine(readme) };
    });
  return { servers, problems };
};

const repositoryOf = (servers: readonly Server[]): Repository => {
  const pkg = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")) as { readonly repository: { readonly url: string }; readonly license: string };
  const url = pkg.repository.url.replace(/^git\+/, "").replace(/\.git$/, "");
  return {
    url,
    name: url.split("/").pop() ?? "",
    license: pkg.license,
    readme: readFileSync(join(ROOT, "README.md"), "utf8"),
    topics: topicsOf(servers.map((s) => s.manifest)),
  };
};

/** Where a repository path leads, for the resolver. */
const kindOf = (path: string): "file" | "dir" | undefined => {
  const full = join(ROOT, path);
  if (!existsSync(full)) return undefined;
  return statSync(full).isDirectory() ? "dir" : "file";
};

const ICON = /^servers\/[^/]+\/icons\/[^/]+$/;

/** Every page, built from the repository as it is on disk. */
export const build = (): Built => {
  const { servers, problems: unread } = readServers();
  if (unread.length > 0) return { pages: [], servers, problems: unread };
  const repository = repositoryOf(servers);
  const layout: Layout = {
    repository: repository.url,
    pages: new Map([["", ""], ...servers.map((s) => [s.manifest.repository.directory, `${s.manifest.repository.directory}/`] as const)]),
    rootAnchors: new Map(AUDIENCES.map((a) => [githubSlug(AUDIENCE[a].heading), `${a}/`] as const)),
    copied: (path) => ICON.test(path) && kindOf(path) === "file",
    kind: kindOf,
  };
  const problems: string[] = [];
  const resolvers: Resolvers = (source, page) => (href, kind) => {
    const { url, problem } = resolveHref(layout, source, page, href, kind);
    if (problem !== undefined) problems.push(`${source === "" ? "" : `${source}/`}README.md: ${problem}`);
    return url;
  };
  if (repository.topics.length > TOPICS_MAX) problems.push(`the repository would have ${repository.topics.length} GitHub topics; GitHub allows ${TOPICS_MAX} (topicsOf, scripts/packaging.ts)`);
  try {
    const pages = [
      landingPage(servers, repository, SITE, resolvers),
      ...AUDIENCES.filter((a) => servers.some((s) => s.manifest.audience === a)).map((a) => audiencePage(a, servers, repository, SITE)),
      ...servers.map((s) => serverPage(s, repository, SITE, resolvers)),
      notFoundPage(repository, SITE),
    ];
    return { pages, servers, problems };
  } catch (error) {
    return { pages: [], servers, problems: [...problems, error instanceof Error ? error.message : String(error)] };
  }
};

/** Writes the site into `out`, emptied first: the pages, the stylesheet with its fonts, the mark, and each server's icons. */
const write = (out: string, built: Built): void => {
  rmSync(out, { recursive: true, force: true });
  for (const page of built.pages) {
    const file = join(out, page.path.endsWith(".html") ? page.path : join(page.path, "index.html"));
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, page.html);
  }
  const fonts = fontFaces();
  mkdirSync(join(out, "assets", "fonts"), { recursive: true });
  for (const { from, to } of fonts.files) cpSync(from, join(out, to));
  const tile = `:root { --color-tile: ${TILE}; --color-tile-ink: ${INK}; }`;
  writeFileSync(join(out, "assets", "site.css"), `${readFileSync(join(ROOT, "scripts", "site", "site.css"), "utf8")}\n${fonts.css}\n${tile}\n`);
  writeFileSync(join(out, "assets", "mark.svg"), iconSvg(SITE_GLYPH));
  for (const { manifest } of built.servers) cpSync(join(ROOT, manifest.repository.directory, "icons"), join(out, manifest.repository.directory, "icons"), { recursive: true });
};

const main = (): void => {
  const args = process.argv.slice(2);
  if (args.includes("--topics")) {
    const { servers } = readServers();
    console.log(topicsOf(servers.map((s) => s.manifest)).join(","));
    return;
  }
  const at = args.indexOf("--out");
  const out = resolve(ROOT, at === -1 ? "_site" : (args[at + 1] ?? "_site"));
  const built = build();
  const problems = [...built.problems];
  if (problems.length === 0) {
    write(out, built);
    problems.push(...checkSite(out, new URL(SITE).pathname));
  }
  if (problems.length > 0) {
    console.error(problems.join("\n"));
    console.error(`\nsite: ${problems.length} problem(s)`);
    process.exit(1);
  }
  console.error(`site: ${built.pages.length} pages in ${out}, every link leads somewhere`);
};

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) main();
